enum Color { RED, BLACK };

// Internal node structure for std::set (BBST e.g., Red-Black Tree)
template <typename T>
struct Node {
    T value;
    Node* parent;
    Node* left;   // Elements where comp(v, value) is true
    Node* right;  // Elements where comp(value, v) is true
    Color color = RED; // Insertion property
};

// Set wrapper manages the root and comparison logic
template <typename T, typename Comp = std::less<T>>
struct SetImpl {
    Node<T>* root = nullptr;
    Comp comp_func;

    // Insertion mechanics rely heavily on comp_func
    // for traversal and maintaining the BBST invariants.
};
